          help: "Select all that apply.",
          options: ["JavaScript", "Python", "HTML", "SQL"],
        },
        {
          id: "typed-languages",
          title: "Which languages are strongly associated with static typing?",
          options: ["TypeScript", "Haskell", "Ruby", "Rust"],
