          id: "web-stack",
          title: "Which languages are commonly used in the web stack?",
          options: ["JavaScript", "HTML", "CSS", "Go"],
        },
      ];

      function QuestionOption(questionId, option, index) {
        const id = `${questionId}-${index}`;
        return `
          <label class="option" for="${id}">
            <input type="checkbox" id="${id}" name="${questionId}" value="${option}" />
            <span>${option}</span>
          </label>
        `;
      }

      function QuestionCard(question) {
        return `
          <div class="form-field">
            <div class="question-header">
              <h2 class="question-title">${question.title}</h2>
              ${
                question.help
                  ? `<p class="help-text">${question.help}</p>`
