      function updateCount() {
        const count = form.querySelectorAll('input[type="checkbox"]:checked').length;
        resultCount.textContent = `${count} selection${count === 1 ? "" : "s"} made`;
      }

      form.addEventListener("change", updateCount);
      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const chosen = quizData
          .map((question) => {
            const values = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`)).map(
              (input) => input.value
            );
            return { question: question.title, values };
          })
          .filter((entry) => entry.values.length > 0);

        summary.hidden = false;
        summary.innerHTML = `
